void dtls_clear_queues(SSL *s) {
    /* Clear unprocessed records queue */
    while (!sk_DTLS1_BUF_USE_EMPTY(s->unprocessed_rcds)) {
        DTLS1_BUF_USE *buf;
        buf = sk_DTLS1_BUF_USE_pop(s->unprocessed_rcds);
        if (buf != NULL) {
            if (buf->buf != NULL)
                OPENSSL_free(buf->buf);
            OPENSSL_free(buf);
        }
    }

    /* Clear processed records queue */
    while (!sk_RECORD_PENDING_EMPTY(s->processed_rcds)) {
        RECORD_PENDING *rec;
        rec = sk_RECORD_PENDING_pop(s->processed_rcds);
        if (rec != NULL) {
            if (rec->data != NULL)
                OPENSSL_free(rec->data);
            OPENSSL_free(rec);
        }
    }

    /* Clear buffered messages queue */
    while (!sk_BUFFERED_RECORD_EMPTY(s->buffered_messages)) {
        BUFFERED_RECORD *rec;
        rec = sk_BUFFERED_RECORD_pop(s->buffered_messages);
        if (rec != NULL) {
            if (rec->data != NULL)
                OPENSSL_free(rec->data);
            OPENSSL_free(rec);
        }
    }

    /* Clear sent messages queue */
    while (!sk_BUFFERED_RECORD_EMPTY(s->sent_messages)) {
        BUFFERED_RECORD *rec;
        rec = sk_BUFFERED_RECORD_pop(s->sent_messages);
        if (rec != NULL) {
            if (rec->data != NULL)
                OPENSSL_free(rec->data);
            OPENSSL_free(rec);
        }
    }

    /* Clear buffered application data queue */
    while (!sk_BUFFERED_RECORD_EMPTY(s->buffered_app_data)) {
        BUFFERED_RECORD *rec;
        rec = sk_BUFFERED_RECORD_pop(s->buffered_app_data);
        if (rec != NULL) {
            if (rec->data != NULL)
                OPENSSL_free(rec->data);
            OPENSSL_free(rec);
        }
    }
}

void dtls_clear_queues(SSL *s) {
    DTLS1_RECORD_DATA *rec_data;
    CRYPTO_BUFFER *buf;
    int i;

    for (i = 0; i < s->s3->rbuf.num_records; i++) {
        rec_data = &s->s3->rbuf.records[i];
        if (rec_data->data != NULL) {
            OPENSSL_free(rec_data->data);
        }
    }

    sk_CRYPTO_BUFFER_pop_free(s->s3->rbuf.buffered, CRYPTO_BUFFER_free);
    sk_CRYPTO_BUFFER_pop_free(s->s3->wbuf.buffered, CRYPTO_BUFFER_free);
    sk_CRYPTO_BUFFER_pop_free(s->d1->sent_messages, CRYPTO_BUFFER_free);
    sk_CRYPTO_BUFFER_pop_free(s->d1->buffered_app_data, CRYPTO_BUFFER_free);
}

void clear_dtls_queues(SSL *s) {
    DTLS1_RECORD_DATA *rd;
    SSL3_BUFFER *buf;

    /* Clear unprocessed records */
    while (!sk_DTLS1_RECORD_DATA_is_empty(s->s3->rrecs)) {
        rd = sk_DTLS1_RECORD_DATA_pop(s->s3->rrecs);
        if (rd->buffer) {
            OPENSSL_free(rd->buffer);
        }
        OPENSSL_free(rd);
    }

    /* Clear processed records */
    while (!sk_DTLS1_RECORD_DATA_is_empty(s->s3->wrecs)) {
        rd = sk_DTLS1_RECORD_DATA_pop(s->s3->wrecs);
        if (rd->buffer) {
            OPENSSL_free(rd->buffer);
        }
        OPENSSL_free(rd);
    }

    /* Clear buffered messages */
    while ((buf = sk_SSL3_BUFFER_pop(s->s3->rbufs)) != NULL) {
        if (buf->buf) {
            OPENSSL_free(buf->buf);
        }
        OPENSSL_free(buf);
    }

    /* Clear sent messages */
    if (s->d1->sent_messages) {
        sk_SSL3_SENT_MSG_BUF_free(s->d1->sent_messages);
        s->d1->sent_messages = NULL;
    }

    /* Clear buffered application data */
    if (s->d1->buffered_app_data) {
        OPENSSL_free(s->d1->buffered_app_data);
        s->d1->buffered_app_data = NULL;
    }
}

